"""Build crawlable static HTML and explicitly selected public assets."""
from pathlib import Path
import json, html, shutil, re, hashlib
from assets import build_assets, ROOT, DEST

OUT=DEST.parent; OUT.mkdir(parents=True,exist_ok=True)
cfg=json.loads((ROOT/'config/site.json').read_text())
photos=build_assets(); byid={p['id']:p for p in photos}
e=lambda x:html.escape(str(x),quote=True)
DOMAIN='https://sdatarneit.au'
PUBLIC_EMAIL='enquiries@sdatarneit.au'
NDIS='https://ndis.gov.au/participants/home-and-living/types-home-and-living-supports/what-specialist-disability-accommodation-sda'
SIL='https://ndis.gov.au/participants/home-and-living/types-home-and-living-supports/what-supported-independent-living-sil'

def img(slug,alt,cls='',eager=False,plan=False):
    widths=[400,1000,2000] if plan else [240,800,1600]
    return f'<img class="{cls}" src="/assets/{slug}-{widths[1]}.webp" srcset="'+', '.join(f'/assets/{slug}-{w}.webp {w}w' for w in widths)+f'" sizes="(max-width: 700px) 100vw, 70vw" alt="{e(alt)}" width="{2583 if plan else 1600}" height="{2600 if plan else 900}" '+('fetchpriority="high" loading="eager"' if eager else 'loading="lazy"')+' decoding="async">'
def photo(n,cls='',eager=False):return img(byid[n]['slug'],byid[n]['caption'],cls,eager)
def link(url,txt,cls='text-link'):return f'<a class="{cls}" href="{url}">{txt}<span aria-hidden="true"> ↗</span></a>'
def section_title(kicker,title,desc=''):return f'<div class="section-heading"><p class="eyebrow">{kicker}</p><h2>{title}</h2>'+ (f'<p>{desc}</p>' if desc else '')+'</div>'
def faq(q,a):return f'<details class="faq"><summary>{q}</summary><div>{a}</div></details>'
def cta():return '<section class="cta-band"><div><p class="eyebrow">YOUR NEXT STEP</p><h2>Let’s talk about the home.</h2><p>Ask about availability or arrange an inspection. Your enquiry reaches the owner, who can answer your questions and coordinate the next step with Disability Forever Homes.</p></div>'+link('/enquiries/','Send an enquiry','button light')+'</section>'

nav='<a href="/">Overview</a><a href="/the-home/">The home</a><a href="/living-in-tarneit/">Life in Tarneit</a><a href="/sda-and-support/">SDA &amp; support</a>'
def page(path,title,description,body):
    canonical=DOMAIN+path
    currentnav=nav.replace(f'href="{path}"',f'href="{path}" aria-current="page"')
    schema={'@context':'https://schema.org','@type':'WebSite','name':'SDA Tarneit','url':DOMAIN} if path=='/' else {'@context':'https://schema.org','@type':'WebPage','name':title,'url':canonical}
    doc=f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{canonical}"><meta name="theme-color" content="#173c33"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{canonical}"><meta property="og:type" content="website"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="stylesheet" href="/styles.css"><script defer src="/app.js"></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="header-inner"><a href="/" class="brand" aria-label="SDA Tarneit home"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M5 20 20 7l15 13M10 17v18h20V17M17 35V23h7v12"/></svg><span>SDA<span class="brand-place">TARNEIT</span></span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Main navigation">{currentnav}</nav><a class="button header-enquire" href="/enquiries/">Enquire <span aria-hidden="true">↗</span></a></div></header><main id="main">{body}</main><footer><div class="footer-top"><a class="footer-brand" href="/">SDA TARNEIT<span>One home. A considered next step.</span></a><div><p>Social Street, Tarneit VIC 3029<br>Wyndham · Melbourne’s western suburbs</p><p><!--email_off--><a href="mailto:{PUBLIC_EMAIL}">Email us: {PUBLIC_EMAIL}</a><!--/email_off--></p></div><div><a href="/enquiries/">Enquiries &amp; inspections</a><a href="/privacy/">Privacy</a><a href="/sda-and-support/">Frequently asked questions</a></div></div><div class="footer-bottom"><p>High Physical Support SDA accommodation on Social Street, Tarneit. Ask about availability or arrange an inspection.</p><span>© 2026 SDA Tarneit</span></div></footer><dialog id="media-dialog" aria-labelledby="media-title"><div class="dialog-top"><div><h2 id="media-title">Property photos</h2><p id="media-note"></p></div><button id="close-dialog" class="icon-button" aria-label="Close media viewer">✕</button></div><div id="media-content"></div><div id="dialog-navigation"><button class="icon-button" id="dialog-prev" aria-label="Previous photo">←</button><p id="dialog-counter" aria-live="polite"></p><button class="icon-button" id="dialog-next" aria-label="Next photo">→</button></div><div id="dialog-thumbnails" aria-label="Choose a photo"></div></dialog></body></html>'''
    for asset in ['styles.css','app.js']:
        version=hashlib.sha256((ROOT/'src'/asset).read_bytes()).hexdigest()[:12]
        doc=doc.replace(f'"/{asset}"',f'"/{asset}?v={version}"')
    folder=OUT/path.strip('/');folder.mkdir(parents=True,exist_ok=True);(folder/'index.html').write_text(doc,encoding='utf-8')

hero_index=photos.index(byid[51])
thumbs=''.join(f'<a href="/assets/{p["slug"]}-1600.webp" class="photo-thumb" data-photo="{i}" aria-label="Photo {i+1}: {e(p["caption"])}"><img src="/assets/{p["slug"]}-240.webp" alt="{e(p["caption"])}" width="240" height="135" loading="lazy"><span>{i+1:02}</span></a>' for i,p in enumerate(photos))
quick=''.join(f'<a href="/assets/{byid[n]["slug"]}-1600.webp" data-main-photo="{photos.index(byid[n])}" aria-label="Show {e(byid[n]["caption"])}"><img src="/assets/{byid[n]["slug"]}-240.webp" width="240" height="135" alt="{e(byid[n]["caption"])}" loading="lazy"></a>' for n in [51,8,29,80,97,108])
gallery=f'''<section class="property-media" aria-label="Explore the property"><div class="media-grid"><div class="main-photo"><a id="main-photo-link" href="/assets/photo-051-1600.webp" data-photo="{hero_index}" aria-label="Enlarge property photo">{photo(51,'hero-image',True)}</a><span class="photo-label">THE ACTUAL HOME</span><div class="main-photo-controls"><button id="main-prev" class="icon-button" aria-label="Previous property photo">←</button><span id="main-counter" aria-live="polite">{hero_index+1} / {len(photos)}</span><button id="main-next" class="icon-button" aria-label="Next property photo">→</button></div></div><div class="media-options"><a class="media-tile" href="#all-photos" data-photo="0">{photo(8)}<span><b>Browse photos</b><small>{len(photos)} property &amp; neighbourhood photos <i aria-hidden="true">↗</i></small></span></a><a class="media-tile" href="/walkthrough/" data-video>{photo(75)}<span><b><i aria-hidden="true">▷</i> Watch walkthrough</b><small>2 min 15 sec <i aria-hidden="true">↗</i></small></span></a><a class="floorplan-tile" href="/the-home/#floorplans"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M5 5h30v30H5zM5 17h14V5M19 17v18M19 26h16M27 5v12h8"/></svg><span><b>View floorplan</b><small>Understand the layout</small></span><i aria-hidden="true">↗</i></a></div></div><div class="quick-thumbs" aria-label="Property photo previews">{quick}<a class="all-photos-button" href="#all-photos">All {len(photos)} photos →</a></div><p class="media-disclaimer">Explore actual property photos from the walkthrough, alongside neighbourhood views. Furniture pictured does not confirm rental inclusions.</p><details id="all-photos" class="photo-collection"><summary>Explore all {len(photos)} photos</summary><div class="thumbnail-grid">{thumbs}</div></details></section>'''

home=f'''<div class="wrap"><section class="intro"><p class="eyebrow">SOCIAL STREET · TARNEIT · VIC 3029</p><div class="intro-line"><div><h1>SDA accommodation in Tarneit.<br><em>A place to feel at home.</em></h1><p class="intro-copy"><strong>Available now:</strong> High Physical Support SDA accommodation in Tarneit, with two participant bedrooms and a separate overnight assistance room.</p></div><a href="/enquiries/" class="text-link intro-cta">Availability &amp; inspections <span aria-hidden="true">↗</span></a></div></section>{gallery}<section class="facts" aria-label="Home at a glance"><div><strong>2</strong><span>Participant bedrooms</span></div><div><strong>+1</strong><span>Overnight assistance room</span></div><div><strong>3</strong><span>Shower bathrooms · no baths</span></div><div><strong>2</strong><span>Garage spaces</span></div></section><section class="split section-space"><div>{section_title('A CLOSER LOOK','Your own space.<br>A home to share.')}<p>This Social Street home brings two participant bedrooms together with a shared kitchen, dining and living area, a covered alfresco and a rear lawn. Each participant bedroom has an adjoining ensuite. There is also a separate bedroom for overnight onsite assistance (OOA).</p><p>One participant bedroom is currently furnished. The second participant bedroom and the overnight assistance room are unfurnished. Ask about furniture and equipment inclusions when you enquire.</p><p>Whether you are looking for yourself, a family member or someone you support, we welcome your questions. Explore the rooms, then tell us what matters to you in a home.</p>{link('/the-home/','Explore the home & accessibility')}</div><figure class="editorial-image">{photo(29)}<figcaption>Participant bedroom one · shown furnished</figcaption></figure></section><section class="feature-links section-space">{section_title('MAKE AN INFORMED CHOICE','Get to know the home, at your pace.')}<div class="three-cards"><article><span class="card-number">01 / THE SPACES</span><h3>See the layout</h3><p>Compare the two participant bedrooms, the OOA room and the shared spaces. The illustrative 2D marketing plan helps you explore how the rooms connect.</p>{link('/the-home/#floorplans','Explore the plans')}</article><article><span class="card-number">02 / YOUR REQUIREMENTS</span><h3>Ask the practical questions</h3><p>Bring your questions about movement through the home, bathroom setup, equipment and support arrangements. Suitability needs an individual check.</p>{link('/the-home/#accessibility','Accessibility & suitability')}</article><article><span class="card-number">03 / YOUR NEXT STEP</span><h3>Arrange a closer look</h3><p>Your enquiry reaches the owner, who can answer questions and coordinate an inspection with Disability Forever Homes.</p>{link('/enquiries/','Enquiries & inspections')}</article></div></section><section class="split reverse section-space"><figure class="editorial-image">{photo(97)}<figcaption>Covered alfresco and the home’s rear garden</figcaption></figure><div>{section_title('LIVING IN TARNEIT','Room for everyday life.')}<p>A home is more than its room count. The outdoor deck, shared dining area and garden offer different spaces to spend time, alongside the privacy of the participant bedrooms.</p><p>Set on Social Street in Tarneit, the home is part of Wyndham in Melbourne’s western suburbs.</p><p>The local park is a short walk of around 50 metres from the house. Explore the neighbourhood photos, including the playground and Tarneit Central shopping centre.</p>{link('/living-in-tarneit/','Explore the neighbourhood')}</div></section><section class="support-intro section-space">{section_title('SDA & SUPPORT','A clear starting point for your questions.')}<div class="two-columns"><div><p>Specialist disability accommodation (SDA) is the housing itself. Daily and overnight support services are arranged separately, with your needs and preferred support team in mind.</p><p>Participants, families, support coordinators and SIL providers are welcome to explore the home and ask questions about the next steps.</p>{link('/sda-and-support/','Understand SDA & support arrangements')}</div><div>{faq('Are there SDA vacancies at this Tarneit home?','<p>Yes. The home is available now for rent. Enquire about the participant rooms, your preferred timing or an inspection.</p>')}{faq('Looking for High Physical Support SDA in Tarneit?','<p>This is High Physical Support SDA accommodation. The owner and property manager can help you explore the home, while your support team can help check its fit with your needs and funding.</p>')}{faq('Can I inspect the home?','<p>Start with an enquiry to the owner. Inspections and suitability checks are coordinated through Disability Forever Homes.</p>')}</div></div></section>{cta()}</div>'''
page('/','SDA Tarneit | High Physical Support home available now','Available now: High Physical Support SDA accommodation on Social Street, Tarneit. Two participant bedrooms with ensuites and a separate OOA room. Enquire today.',home)

plans=f'''<section id="floorplans" class="section-space">{section_title('UNDERSTAND THE LAYOUT','Two different views. One actual home.','Use the 2D plan to understand the layout. Use the 3D concept only to imagine how furnished spaces might look.')}<div class="plan-grid"><article><a href="/assets/tarneit-floor-plan.svg" data-plan="2d">{img('plan-2d','2D floor plan showing two participant bedrooms, OOA room, three shower bathrooms and the site layout',plan=True)}</a><p class="eyebrow">LAYOUT REFERENCE</p><h3>2D floor plan</h3><p>An illustrative 2D marketing floorplan showing the rooms and outdoor layout. Use it to explore the home, then check dimensions during an inspection. It is not a construction drawing.</p><div class="link-row">{link('/assets/tarneit-floor-plan.pdf','Download PDF')}{link('/assets/tarneit-floor-plan.svg','Open full-size plan')}</div></article><article><a href="/assets/plan-3d-2000.webp" data-plan="3d">{img('plan-3d','Illustrative furnished 3D concept of the home, not a photograph or authoritative floorplan',plan=True)}</a><p class="eyebrow">ILLUSTRATIVE FURNISHED CONCEPT</p><h3>3D concept view</h3><p>An illustrative furnished 3D concept to help you picture the spaces. It is not a photograph; furniture and fittings may differ from the actual home.</p><p>Furniture pictured does not establish what is included.</p>{link('/assets/plan-3d-2000.webp','Open concept image')}</article></div></section>'''
features=f'''<div class="wrap"><section class="page-intro"><p class="eyebrow">THE SOCIAL STREET HOME</p><h1>Spaces to make your own.</h1><p>Two participant bedrooms, a separate overnight assistance room and shared spaces for everyday living.</p></section><div class="wide-image">{photo(72,'',True)}</div><section class="section-space two-columns"><div><h2>Bedrooms and bathrooms</h2><p>The home has two participant bedrooms, each with its own ensuite, and a separate bedroom for overnight onsite assistance (OOA).</p><p>All three bathrooms have showers; there are no baths.</p><p>One participant bedroom is currently furnished. The second participant bedroom and the overnight assistance room are unfurnished. Furniture shown does not confirm what is included in the rental.</p></div><div><h2>Shared living and outdoors</h2><p>The shared kitchen, dining and living spaces bring everyday life together, with a covered alfresco for time outdoors.</p><p>The garden and rear lawn offer another place to spend time, alongside the privacy of your own bedroom.</p><p>A double garage and laundry complete the home. An inspection is a good opportunity to explore the spaces and discuss how they could work for you.</p></div></section><section id="accessibility" class="tinted section-space">{section_title('ACCESSIBILITY & SUITABILITY','Look closely. Ask specifically.')}<p>This High Physical Support SDA home may be part of your next step towards a home that works for you. During an inspection, you can explore the layout and discuss your individual access and equipment needs.</p><div class="two-columns"><div><h3>Useful questions for an inspection</h3><ul class="check-list"><li>Do the doorways, turning spaces and routes work with your mobility equipment?</li><li>Does the shower, toilet and transfer layout meet your requirements?</li><li>How do the entrance, driveway and alfresco transitions work for you?</li></ul></div><div><h3>Equipment and support</h3><ul class="check-list"><li>Which equipment is installed, and what would you need to bring or arrange?</li><li>What power, hoist or assistive-technology requirements would you like to discuss?</li><li>How would overnight assistance and daily supports be organised?</li></ul></div></div><p>The owner can coordinate an inspection and individual suitability check with Disability Forever Homes. You are welcome to bring a family member, support coordinator or provider to help you consider the home.</p></section>{plans}{cta()}</div>'''
page('/the-home/','The home & accessibility | SDA Tarneit','Explore the Social Street home’s bedrooms, shower bathrooms, shared spaces and outdoor areas. View the 2D layout and separately labelled 3D concept.',features)

location=f'''<div class="wrap"><section class="page-intro"><p class="eyebrow">TARNEIT · WYNDHAM · MELBOURNE’S WEST</p><h1>Everyday life in Tarneit.</h1><p>Get a feel for the surroundings, then check the places and routes that matter in your day-to-day life.</p></section><section class="location-grid"><article>{img('nearby-playground','Aerial photograph of the local playground and surrounding paths',eager=True)}<div><p class="eyebrow">TIME OUTDOORS</p><h2>Local playground & open space</h2><p>The local park and playground are a short walk of around 50 metres from the house, making it easy to step out for a change of scene. Explore the paths and open space when you visit.</p></div></article><article>{img('nearby-shopping','Aerial photograph of Tarneit Central shopping centre')}<div><p class="eyebrow">EVERYDAY AMENITIES</p><h2>Tarneit Central</h2><p>Tarneit Central is one of the local shopping destinations to consider as you get to know the area. Plan visits around the shops and services you use, and the transport and support that work for you.</p></div></article></section><aside class="note">Plan a visit around your usual routine and check the paths, crossings and transport options that matter to you.</aside><section class="section-space two-columns"><div><h2>Considering SDA in Wyndham?</h2><p>If you are exploring SDA accommodation in Melbourne’s western suburbs, the Social Street home offers two participant bedrooms with ensuites and shared spaces in Tarneit, within Wyndham.</p><p>Tell us what you are looking for in your next home. The owner can answer questions about this property and help arrange a closer look.</p></div><div><h2>Plan the trips that matter to you</h2><ul class="check-list"><li>Choose the shops, activities and services that are important to your routine.</li><li>Check paths, crossings and entrances using your own access requirements.</li><li>Discuss transport and support arrangements with your support team.</li><li>Use an inspection to assess the arrival route and driveway, not just the rooms.</li></ul><p>An inspection can help you get a feel for both the home and its surroundings.</p></div></section>{cta()}</div>'''
page('/living-in-tarneit/','Living in Tarneit, Wyndham | SDA Tarneit','Explore life near Social Street, Tarneit, in Melbourne’s western suburbs. The local park is a short walk of around 50 metres from the home.',location)

support=f'''<div class="wrap narrow"><section class="page-intro"><p class="eyebrow">SDA, SUPPORT & YOUR QUESTIONS</p><h1>Understand the home.<br>Clarify the support.</h1><p>A practical starting point for participants, families, support coordinators and SIL providers.</p></section><section class="section-space"><h2>SDA and daily supports are different</h2><p>Specialist disability accommodation is housing designed for people with extreme functional impairment or very high support needs. SDA is about the home; it does not include daily support services such as supported independent living (SIL).</p><p>Discuss housing and your day-to-day support arrangements separately. The presence of an overnight onsite assistance room does not establish the hours, staffing or provider of support.</p><p class="source">Read the official NDIS guidance on <a href="{NDIS}">specialist disability accommodation</a> and <a href="{SIL}">supported independent living</a>.</p></section><section class="tinted"><p class="eyebrow">HIGH PHYSICAL SUPPORT</p><h2>Looking for HPS accommodation in Tarneit?</h2><p>The Social Street home is High Physical Support SDA accommodation, available now for rent. It has two participant bedrooms, each with an ensuite, and a separate overnight assistance room.</p><p>You do not need to have every detail settled before enquiring. Ask about the home, then work with your support team and the property manager to check individual suitability and funding.</p></section><section class="section-space"><h2>Frequently asked questions</h2>{faq('How many participant bedrooms are there?','<p>There are two participant bedrooms, each with an ensuite, plus a separate overnight onsite assistance (OOA) bedroom.</p>')}{faq('How many bathrooms are there?','<p>All three bathrooms have showers; there are no baths.</p>')}{faq('Is this home currently available?','<p>Yes, the home is available now for rent. Ask about the participant rooms, your preferred move-in timing or arranging an inspection.</p>')}{faq('Is furniture included?','<p>One participant bedroom is currently furnished. The second participant bedroom and the overnight assistance room are unfurnished. Ask the owner what furniture, if any, would be included in the rental.</p>')}{faq('Who provides SIL or overnight support?','<p>Daily and overnight support are arranged separately from the accommodation. Discuss your preferred provider and support needs with your support team and the property manager.</p>')}{faq('Will my NDIS funding cover this home?','<p>This website cannot determine eligibility or the match between your plan and a property. Speak with your support coordinator or the NDIS and ask for current property enrolment information.</p>')}{faq('Who will arrange an inspection?','<p>Send your questions to the owner first. Disability Forever Homes, the property manager, coordinates inspections and suitability checks.</p>')}{faq('Can I enquire before funding or support is arranged?','<p>Yes. Participants, families, support coordinators and SIL providers are welcome to ask questions. You do not need confirmed SDA funding or a SIL provider to make an initial enquiry.</p>')}{faq('Does this website list other SDA homes in western Melbourne?','<p>No. It showcases one actual SDA home on Social Street in Tarneit, within Wyndham.</p>')}</section>{cta()}</div>'''
page('/sda-and-support/','SDA, High Physical Support & support FAQs | SDA Tarneit','Understand SDA and support arrangements, the OOA bedroom, HPS questions, furniture and inspections at this Tarneit home. Read practical accommodation FAQs.',support)

enquiries='''<div class="wrap"><section class="page-intro"><p class="eyebrow">ENQUIRIES &amp; INSPECTIONS</p><h1>Let’s start with your questions.</h1><p><strong>Available now:</strong> High Physical Support SDA accommodation in Tarneit, with two participant bedrooms and a separate overnight assistance room.</p></section><div class="enquiry-layout"><section class="enquiry-context"><h2>Ask about availability or arrange an inspection.</h2><p>Your initial enquiry reaches the owner of the Social Street home. They can answer your questions and coordinate the next step with Disability Forever Homes, the property manager.</p><p>Choose the form, or email us directly at <!--email_off--><a href="mailto:{PUBLIC_EMAIL}">{PUBLIC_EMAIL}</a><!--/email_off-->.</p><ol class="steps"><li><strong>Tell us what you’re looking for</strong><span>Ask a question about the home, the available rooms or an inspection.</span></li><li><strong>Hear from the owner</strong><span>The owner will use the contact details you provide to respond.</span></li><li><strong>Explore the next step</strong><span>Arrange a closer look and discuss individual suitability with the property manager.</span></li></ol><p>Participants, families, support coordinators and SIL providers are all welcome. You do not need confirmed SDA funding or a SIL provider to ask a question.</p></section><section class="form-panel"><h2>Send an enquiry</h2><p id="form-availability">A few details are enough to start a conversation.</p><form id="enquiry-form" action="/api/enquiries" method="post"><fieldset id="enquiry-fields" disabled><legend class="sr-only">Your enquiry details</legend><div class="field-row"><label>Your name <span>(required)</span><input name="name" autocomplete="name" required maxlength="100"></label><label>Email <span>(required)</span><input type="email" name="email" autocomplete="email" required maxlength="254"></label></div><div class="field-row"><label>Phone <span>(optional)</span><input type="tel" name="phone" autocomplete="tel" maxlength="40"></label><label>I am enquiring as<select name="role"><option>A participant</option><option>A family member</option><option>A support coordinator</option><option>A SIL provider</option><option>Someone else</option></select></label></div><label>I’d like to ask about<select name="topic"><option>The home and suitability</option><option>Current availability</option><option>Arranging an inspection</option><option>Something else</option></select></label><label>Your questions <span>(required)</span><textarea name="message" rows="5" required minlength="10" maxlength="4000" aria-describedby="message-help"></textarea></label><p id="message-help" class="field-help">Please do not send medical documents, NDIS numbers or other sensitive records. If you are enquiring for someone else, share only what they are comfortable with.</p><div class="honeypot" aria-hidden="true"><label>Leave this blank<input name="website" tabindex="-1" autocomplete="off" maxlength="100"></label></div><label class="checkbox"><input type="checkbox" name="consent" required><span>I agree to be contacted about my enquiry and have read the <a href="/privacy/">privacy information</a>.</span></label><button type="submit" class="button">Send enquiry</button></fieldset><noscript><p>Please enable JavaScript to use this enquiry form. The form cannot send while JavaScript is disabled.</p></noscript><p id="form-result" role="status" aria-live="polite" tabindex="-1"></p></form></section></div></div>'''.replace('{PUBLIC_EMAIL}',PUBLIC_EMAIL)
page('/enquiries/','Availability & inspections | SDA Tarneit','Available now: High Physical Support SDA accommodation on Social Street, Tarneit. Send the owner an enquiry about the home or arranging an inspection.',enquiries)

privacy='''<div class="wrap narrow"><section class="page-intro"><p class="eyebrow">YOUR INFORMATION</p><h1>Privacy &amp; enquiries</h1><p>Share just enough to start a conversation about the home.</p></section><section class="section-space prose"><h2>What we collect</h2><p>The enquiry form collects your name, email address, optional phone number, who you are enquiring as, enquiry purpose and message, together with your consent to be contacted. We add a submission time and unique enquiry reference. If you email us directly, we receive the sender address and the message and attachments you choose to include.</p><p>Please do not submit medical documents, NDIS participant numbers, financial documents or other sensitive records. If you are enquiring for someone else, share only information they are comfortable with you providing.</p><h2>How enquiries are stored and used</h2><p>Form submissions are sent over an encrypted connection and saved as private files on the website’s server for the owner to review. These files are outside the public website and cannot be accessed through a website link. They are not stored in your browser or published online.</p><p>The website emails form details through Resend, our email delivery provider, to the owner’s Gmail. The notification includes your name, contact details, enquiry purpose, message, submission time and reference, with a JSON copy attached. Resend processes the message to deliver it, and Google receives it in the owner’s mailbox. If email delivery is delayed or fails, the enquiry remains saved on the website’s server.</p><p>Messages sent directly to <!--email_off--><a href="mailto:{PUBLIC_EMAIL}">{PUBLIC_EMAIL}</a><!--/email_off--> are forwarded by Cloudflare Email Routing to the owner’s Gmail. Cloudflare and Google process that email to deliver it. Direct emails are handled in the owner’s mailbox; they are not saved as website enquiry files.</p><p>The owner uses your details to answer your questions and discuss availability or an inspection. They can coordinate the next step with Disability Forever Homes, the property manager. Any further sharing of your personal information can be discussed with you as part of that conversation.</p><p>Website enquiry files remain on the server until the owner removes them. There is no automatic deletion schedule. Email copies remain in the owner’s mailbox until removed there. You can use the <a href="/enquiries/">enquiry form</a> or email us to ask to access, correct or delete information you have submitted; include your enquiry reference if you have it.</p><h2>When your enquiry is received</h2><p>A thank-you message appears only after a form enquiry has been saved. If saving fails, the form keeps your entries so you can retry. Receiving an enquiry does not reserve a room or confirm an inspection time.</p><h2>Website operation</h2><p>Cloudflare carries website traffic, including form submissions, between your browser and our server. Technical request information may be processed in network logs. The application uses your network address temporarily in memory to limit spam; it is not saved with your enquiry. Form enquiry content is not written to application logs.</p><p>The website has no advertising trackers, analytics scripts or external video embeds. Photos and the walkthrough are served directly from this website.</p></section></div>'''.replace('{PUBLIC_EMAIL}',PUBLIC_EMAIL)
page('/privacy/','Privacy & enquiry information | SDA Tarneit','How SDA Tarneit collects, privately stores and uses accommodation enquiries, and how to request access, correction or deletion.',privacy)
walkthrough=f'''<div class="wrap narrow"><section class="page-intro"><p class="eyebrow">EXPLORE THE ACTUAL HOME</p><h1>Walk through Social Street.</h1><p>A recorded walkthrough · 2 min 15 sec. Press play when you’re ready.</p></section><video class="walkthrough-video" controls playsinline preload="none" poster="/assets/photo-051-800.webp" src="/assets/tarneit-720p.mp4" aria-label="Recorded walkthrough of the Social Street home"></video><p class="media-disclaimer">This walkthrough shows the actual home. Some on-screen captions are from earlier marketing, including an old postcode; the home is in Tarneit VIC 3029. Furniture and equipment pictured do not confirm rental inclusions.</p><section class="section-space"><h2>A text guide to the walkthrough</h2><p>The video starts outside the home and moves through the entrance, the overnight assistance room and its shower ensuite. It then shows the furnished first participant bedroom and ensuite, the shared kitchen, dining and living areas, and the second participant bedroom and ensuite.</p><p>The final section shows the alfresco, rear garden, garage, laundry, air conditioning and alarm panel, followed by nearby playground and shopping-centre imagery. The <a href="/the-home/">home page</a> describes the layout and the <a href="/#all-photos">photo gallery</a> provides labelled stills of these spaces.</p><p>Ready to take a closer look? Ask about availability or arrange an inspection with the owner.</p></section>{cta()}</div>'''
page('/walkthrough/','Property walkthrough — 2 min 15 sec | SDA Tarneit','Watch the recorded walkthrough of the Social Street home in Tarneit, with a text guide and labelled photo alternatives.',walkthrough)

